/// <summary>
/// Complete batch job export for cross-environment migration
/// </summary>
using System.IO;
public class METBatchJobMigrationExport extends RunBaseBatch
{
    QueryRun                queryRun;
    boolean                 onlyWithRecurrence;
    METFileWriterExcel      writer;  // Framework!

    DialogField dlgOnlyWithRecurrence;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        onlyWithRecurrence
    #endmacro

    #define.ExcelFileName('BatchJobMigration')
    #define.MaxChunkSize(32000)
    #define.MaxParameterChunks(10)
    #define.MaxRecurrenceChunks(5)

}

Method.Source:
/// <summary>
/// Dialog construction
/// </summary>
public Object dialog()
{
    DialogRunbase dialog = super();

    dlgOnlyWithRecurrence = dialog.addFieldValue(
        extendedTypeStr(NoYesId),
        onlyWithRecurrence,
        "Only with Recurrence",
        "Export only batch jobs that have recurrence configured"
    );

    return dialog;
}

/// <summary>
/// Get values from dialog
/// </summary>
public boolean getFromDialog()
{
    onlyWithRecurrence = dlgOnlyWithRecurrence.value();

    // Call super to get query modifications from dialog
    return super();
}

/// <summary>
/// Initialize default parameters
/// </summary>
public void initParmDefault()
{
    super();
    this.initQuery();
    onlyWithRecurrence = NoYes::No;
}

/// <summary>
/// Initialize query
/// </summary>
public void initQuery()
{
    Query                   query;
    QueryBuildDataSource    qbdsBatchJob, qbdsBatch;
    QueryBuildRange         qbrJobDate, qbrJobStatus;
    QueryBuildRange         qbrBatchStatus, qbrClassName, qbrRunTimeTask;
    utcDateTime             oneMonthAgo;

    query = new Query();
    qbdsBatchJob = query.addDataSource(tableNum(BatchJob));

    // Add sorting: Status, Company, Caption
    qbdsBatchJob.addSortField(fieldNum(BatchJob, Status));
    qbdsBatchJob.addSortField(fieldNum(BatchJob, Company));
    qbdsBatchJob.addSortField(fieldNum(BatchJob, Caption));

    // Range 1: BatchJob OrigStartDateTime >= 1 month ago (user can modify)
    oneMonthAgo = DateTimeUtil::addMonths(DateTimeUtil::utcNow(), -1);
    qbrJobDate = qbdsBatchJob.addRange(fieldNum(BatchJob, OrigStartDateTime));
    qbrJobDate.value(SysQueryRangeUtil::greaterThanUtcDate(-30));

    // Range 2: BatchJob Status = HOLD, WAITING, EXECUTING, READY (user can modify)
    qbrJobStatus = qbdsBatchJob.addRange(fieldNum(BatchJob, Status));
    qbrJobStatus.value(
        strFmt('%1,%2,%3,%4',
            enum2Str(BatchStatus::Hold) ,
            enum2Str(BatchStatus::Waiting),
            enum2Str(BatchStatus::Executing),
            enum2Str(BatchStatus::Ready)));

    // Add Batch table datasource with pre-configured ranges
    qbdsBatch = qbdsBatchJob.addDataSource(tableNum(Batch));
    qbdsBatch.joinMode(JoinMode::InnerJoin);
    qbdsBatch.relations(true);

    // Range 1: BatchJob Status != ENDED, ERROR, CANCELLED (user can modify)
    qbrRunTimeTask = qbdsBatch.addRange(fieldNum(Batch, RunTimeTask));
    qbrRunTimeTask.value(SysQuery::value(boolean::false)); // Exclude RunTimeTask = Yes

    queryRun = new QueryRun(query);
}

/// <summary>
/// Get query run object
/// </summary>
public QueryRun queryRun()
{
    return queryRun;
}

/// <summary>
/// Generate file name with timestamp
/// </summary>
private str generateFileName()
{
    utcDateTime currentDateTime = DateTimeUtil::getSystemDateTime();
    date        currentDate = DateTimeUtil::date(currentDateTime);
    timeOfDay   currentTime = DateTimeUtil::time(currentDateTime);
    str         year, month, day, hour, minute;

    year    = int2Str(year(currentDate));
    month   = strLFix(int2Str(mthOfYr(currentDate)), 2, '0');
    day     = strLFix(int2Str(dayOfMth(currentDate)), 2, '0');
    hour    = strRFix(int2Str(currentTime div 3600), 2, '0');
    minute  = strRFix(int2Str((currentTime mod 3600) div 60), 2, '0');

    return strFmt('%1_%2_%3_%4_%5%6',
        #ExcelFileName,
    year,
        month,
        day,
        hour,
        minute
    );
}

/// <summary>
/// Check if job has recurrence
/// </summary>
private boolean hasRecurrence(BatchJob _batchJob)
{
    return _batchJob.recurrenceData ? true : false;
}

/// <summary>
/// Check if job has EndAfter recurrence type (TEMPORARY - remove when ready to support EndAfter)
/// </summary>
private boolean hasEndAfterRecurrence(BatchJob _batchJob)
{
    if (!_batchJob.recurrenceData)
    {
        return false;
    }

    // Parse recurrence container to check endDateRadio
    // Container format: [version, startTime, startDate, endDateRadio, endDateInt, endDateDate, unit, pattern, timezone]
    // endDateRadio: 1 = NoEnd, 2 = EndAfter, 3 = EndBy
    int version, startTime, endDateRadio, endDateInt, unit, timezone;
    date startDate, endDateDate;
    container pattern;

    try
    {
        [version, startTime, startDate, endDateRadio, endDateInt, endDateDate, unit, pattern, timezone] = _batchJob.recurrenceData;
        return (endDateRadio == 2); // 2 = EndAfter
    }
    catch
    {
        return false;
    }
}

/// <summary>
/// Main execution
/// </summary>
public void run()
{
    super();

    // Reset query for actual export - preserve user's query filters from dialog
    queryRun = new QueryRun(queryRun.query());

    // Initialize framework writer
    writer = new METFileWriterExcel();
    writer.parmWorkSheetNameStr(this.generateFileName());

    // Write header
    this.writeHeaderRow();

    // Write data
    this.writeDataRows();

    // Finalize and download
    this.finalizeExport();
}

/// <summary>
/// Write header row
/// </summary>
private void writeHeaderRow()
{
    container header = conNull();
    int recurrenceChunk, paramChunk;

    // Basic job fields
    header += 'Job Id';
    header += 'Job Status';
    header += 'Job Caption';
    header += 'Job Company';
    header += 'Batch Group';
    header += 'Run By';
    header += 'Scheduled Start DateTime(UserTZ)';
    header += 'UserTZ';

    // Additional job fields
    header += 'Scheduling Priority';
    header += 'Priority Overridden';
    header += 'Log Level';
    header += 'Critical';
    header += 'Monitoring Category';
    header += 'Managed';
    header += 'Active Period';
    header += 'Alerts';

    // Task fields
    header += 'Task Caption';
    header += 'Task Company';
    header += 'Class Name';
    header += 'Task Sequence';
    header += 'Depends On Tasks';
    header += 'Constraint Type';
    header += 'Expected Status';
    header += 'Maximum Retries';

    // Recurrence breakdown columns (19 columns - includes Recur_StartDateTime)
    header += 'Recur_StartDateTime';
    header += 'Recur_Timezone';
    header += 'Recur_EndType';
    header += 'Recur_EndAfterCount';
    header += 'Recur_EndByDate';
    header += 'Recur_Unit';
    header += 'Recur_Interval';
    header += 'Recur_DayType';
    header += 'Recur_WeekInterval';
    header += 'Recur_WeekDays';
    header += 'Recur_MonthType';
    header += 'Recur_MonthDay';
    header += 'Recur_MonthInterval';
    header += 'Recur_MonthWeek';
    header += 'Recur_MonthWeekday';
    header += 'Recur_YearType';
    header += 'Recur_YearWeek';
    header += 'Recur_YearWeekday';
    header += 'Recur_YearMonth';

    // Parameters chunks
    for (paramChunk = 1; paramChunk <= #MaxParameterChunks; paramChunk++)
    {
        if (paramChunk == 1)
        {
            header += 'Parameters';
        }
        else
        {
            header += strFmt('Parameters%1', paramChunk);
        }
    }

    writer.addContainerLine(header);
    writer.markRowAsBold();
}

/// <summary>
/// Write all data rows
/// </summary>
private void writeDataRows()
{
    BatchJob        batchJob;
    Batch           batchTask;
    RecId           currentBatchJobRecId = 0;
    int             taskSequence = 0;

    while (queryRun.next())
    {
        batchJob = queryRun.get(tableNum(BatchJob));
        batchTask = queryRun.get(tableNum(Batch));

        // Check if we moved to a new BatchJob
        if (batchJob.RecId != currentBatchJobRecId)
        {
            currentBatchJobRecId = batchJob.RecId;
            taskSequence = 0;

            // Skip jobs without recurrence if filter is enabled
            if (onlyWithRecurrence && !this.hasRecurrence(batchJob))
            {
                continue;
            }

            // Skip jobs with EndAfter recurrence
            if (onlyWithRecurrence && this.hasEndAfterRecurrence(batchJob))
            {
                continue;
            }
        }

        // Skip task if it uses excluded classes
        if (batchTask.ClassNumber == classNum(CustAccountStatementExtController)
        // || batchTask.ClassNumber == classNum(METSalesPickingListGenerationTaskController)
        || batchTask.ClassNumber == classNum(SysIntegrationActivityBatch)
         || batchTask.ClassNumber == classNum(SysOperationController))
        {
            continue;
        }

        taskSequence++;

        // Build complete row as container
        container dataRow = this.buildDataRow(batchJob, batchTask, taskSequence);

        writer.addContainerLine(dataRow);
    }
}

/// <summary>
/// Build complete data row as container
/// </summary>
private container buildDataRow(BatchJob _batchJob, Batch _batchTask, int _taskSequence)
{
    container row = conNull();
    int i;

    // Basic job fields
    row += _batchJob.RecId;
    row += enum2Str(_batchJob.Status);
    row += _batchJob.Caption;
    row += _batchJob.Company;  // Job Company from BatchJob table
    row += _batchJob.BatchGroup;
    row += _batchJob.ExecutingBy;

    // Convert OrigStartDateTime to user timezone
    Timezone userTz = DateTimeUtil::getUserPreferredTimeZone();
    utcDateTime scheduledDateTime = _batchJob.OrigStartDateTime;
    utcDateTime scheduledDateTimeUserTz = DateTimeUtil::applyTimeZoneOffset(scheduledDateTime, userTz);
    row += DateTimeUtil::toStr(scheduledDateTimeUserTz);
    row += enum2Str(userTz);

    // Additional job fields
    row += enum2Str(_batchJob.SchedulingPriority);
    row += enum2Str(_batchJob.SchedulingPriorityIsOverridden);
    row += enum2Str(_batchJob.LogLevel);
    row += enum2Str(_batchJob.Critical);
    row += enum2Str(_batchJob.MonitoringCategory);
    row += enum2Str(_batchJob.Managed);
    row += _batchJob.ActivePeriod;
    row += this.getAlertsString(_batchJob.RecId);

    // Task fields
    row += _batchTask.Caption;
    row += _batchTask.Company;  // Task Company from Batch table
    row += classId2Name(_batchTask.ClassNumber);
    row += int642Str(_batchTask.RecId); // Task Sequence = Batch table RecId
    row += this.getDependsOnTasks(_batchTask.RecId);
    row += enum2Str(_batchTask.ConstraintType);
    row += this.getExpectedStatus(_batchTask.RecId);
    row += int2Str(_batchTask.retriesOnFailure);

    // Recurrence breakdown columns (19 columns - includes Recur_StartDateTime)
    if (_taskSequence == 1 && _batchJob.recurrenceData)
    {
        row += this.buildRecurrenceBreakdownContainer(_batchJob.recurrenceData, _batchJob.OrigStartDateTime);
    }
    else
    {
        // Empty recurrence breakdown (19 empty values)
        for (i = 1; i <= 19; i++)
        {
            row += '';
        }
    }

    // Parameters chunks
    if (_batchTask.Parameters)
    {
        str paramBase64 = this.containerToBase64String(_batchTask.Parameters);
        container paramChunks = this.splitIntoChunks(paramBase64, #MaxParameterChunks);

        for (i = 1; i <= conLen(paramChunks); i++)
        {
            row += conPeek(paramChunks, i);
        }

        // Fill remaining empty chunks
        for (i = conLen(paramChunks) + 1; i <= #MaxParameterChunks; i++)
        {
            row += '';
        }
    }
    else
    {
        // No parameters - empty chunks
        for (i = 1; i <= #MaxParameterChunks; i++)
        {
            row += '';
        }
    }

    return row;
}

/// <summary>
/// Build recurrence breakdown as container (19 values)
/// </summary>
private container buildRecurrenceBreakdownContainer(container _recurrenceData, utcDateTime _origStartDateTime)
{
    container breakdown = conNull();

    if (!_recurrenceData)
    {
        // Return 18 empty values (removed Recur_StartDateTime)
        int i;
        for (i = 1; i <= 18; i++)
        {
            breakdown += '';
        }
        return breakdown;
    }

    // Parse recurrence container
    int version, startTime, endDateRadio, endDateInt;
    date startDate, endDateDate;
    int unit;
    container pattern;
    int timezone;

    [version, startTime, startDate, endDateRadio, endDateInt, endDateDate, unit, pattern, timezone] = _recurrenceData;

    // StartDateTime - export from recurrence data converted to recurrence timezone
    utcDateTime recurrenceStartDateTimeUTC = DateTimeUtil::newDateTime(startDate, startTime);
    utcDateTime recurrenceStartDateTimeInTZ = DateTimeUtil::applyTimeZoneOffset(recurrenceStartDateTimeUTC, timezone);
    breakdown += DateTimeUtil::toStr(recurrenceStartDateTimeInTZ);

    // Timezone - use the timezone from recurrence data (cast int to Timezone enum)
    Timezone tz = timezone;
    breakdown += enum2Str(tz);

    // EndType
    breakdown += (endDateRadio == 1 ? 'NoEnd' : (endDateRadio == 2 ? 'EndAfter' : 'EndBy'));

    // EndAfterCount
    breakdown += (endDateRadio == 2 ? int2Str(endDateInt) : '');

    // EndByDate
    breakdown += (endDateRadio == 3 ? date2Str(endDateDate, 321, DateDay::Digits2, DateSeparator::Slash, DateMonth::Digits2, DateSeparator::Slash, DateYear::Digits4) : '');

    // Unit - convert int to string
    str unitStr = '';
    switch (unit)
    {
        case 0: unitStr = 'Minute'; break;
        case 1: unitStr = 'Hour'; break;
        case 2: unitStr = 'Day'; break;
        case 3: unitStr = 'Week'; break;
        case 4: unitStr = 'Month'; break;
        case 5: unitStr = 'Year'; break;
    }
    breakdown += unitStr;

    // Pattern-specific fields (13 values)
    breakdown += this.buildPatternBreakdownContainer(unit, pattern);

    return breakdown;
}

/// <summary>
/// Build pattern-specific breakdown (13 values)
/// </summary>
private container buildPatternBreakdownContainer(int _unit, container _pattern)
{
    container patternBreakdown = conNull();

    switch (_unit)
    {
        case 0: // Minute
        case 1: // Hour
            patternBreakdown = this.buildMinuteHourBreakdown(_pattern);
            break;

        case 2: // Day
            patternBreakdown = this.buildDayBreakdown(_pattern);
            break;

        case 3: // Week
            patternBreakdown = this.buildWeekBreakdown(_pattern);
            break;

        case 4: // Month
            patternBreakdown = this.buildMonthBreakdown(_pattern);
            break;

        case 5: // Year
            patternBreakdown = this.buildYearBreakdown(_pattern);
            break;

        default:
            // Empty 13 values
            int i;
            for (i = 1; i <= 13; i++)
            {
                patternBreakdown += '';
            }
            break;
    }

    return patternBreakdown;
}

/// <summary>
/// Minute/Hour pattern breakdown (13 values: 1 + 12 empty)
/// </summary>
private container buildMinuteHourBreakdown(container _pattern)
{
    container breakdown = conNull();
    int interval;
    int i;

    [interval] = _pattern;

    breakdown += int2Str(interval);  // Interval
    breakdown += '';                 // DayType (empty)

    // 11 empty values for Week/Month/Year fields
    for (i = 1; i <= 11; i++)
    {
        breakdown += '';
    }

    return breakdown;
}

/// <summary>
/// Day pattern breakdown (13 values: 2 + 11 empty)
/// </summary>
private container buildDayBreakdown(container _pattern)
{
    container breakdown = conNull();
    int type, interval;
    int i;

    [type, interval] = _pattern;

    breakdown += int2Str(interval);                              // Interval
    breakdown += (type == 1 ? 'PerDays' : 'EveryWeekday');      // DayType

    // 11 empty values for Week/Month/Year fields
    for (i = 1; i <= 11; i++)
    {
        breakdown += '';
    }

    return breakdown;
}

/// <summary>
/// Week pattern breakdown (13 values: 2 + 11, but skip first 2)
/// </summary>
private container buildWeekBreakdown(container _pattern)
{
    container breakdown = conNull();
    int weekInterval, weekDaysPattern;
    str daysList;
    int i;

    [weekInterval, weekDaysPattern] = _pattern;

    // Skip Interval and DayType (2 empty)
    breakdown += '';
    breakdown += '';

    // WeekInterval
    breakdown += int2Str(weekInterval);

    // WeekDays - decode bit pattern
    // Note: D365 uses 31 to represent "Weekdays" (Mon-Fri), need to convert to proper bit flags
    if (weekDaysPattern == 31) // D365's constant for Weekdays (Mon-Fri)
    {
        weekDaysPattern = 62; // Convert to proper bit flags (2+4+8+16+32)
    }

    daysList = '';
    if (weekDaysPattern & 2) daysList += 'MON,';
    if (weekDaysPattern & 4) daysList += 'TUE,';
    if (weekDaysPattern & 8) daysList += 'WED,';
    if (weekDaysPattern & 16) daysList += 'THU,';
    if (weekDaysPattern & 32) daysList += 'FRI,';
    if (weekDaysPattern & 64) daysList += 'SAT,';
    if (weekDaysPattern & 1) daysList += 'SUN,';
    if (daysList) daysList = subStr(daysList, 1, strLen(daysList) - 1);

    breakdown += daysList;

    // 9 empty values for Month/Year fields
    for (i = 1; i <= 9; i++)
    {
        breakdown += '';
    }

    return breakdown;
}

/// <summary>
/// Month pattern breakdown (13 values)
/// </summary>
private container buildMonthBreakdown(container _pattern)
{
    container breakdown = conNull();
    int type, day, perMonth1, perMonth2;
    int weekOfMonth, dayValue;
    int i;

    [type, day, perMonth1, weekOfMonth, dayValue, perMonth2] = _pattern;

    // Skip first 4 columns (Interval, DayType, WeekInterval, WeekDays)
    for (i = 1; i <= 4; i++)
    {
        breakdown += '';
    }

    // MonthType
    breakdown += (type == 1 ? 'SpecificDay' : 'SpecificWeekday');

    if (type == 1) // Specific day
    {
        breakdown += int2Str(day);          // MonthDay
        breakdown += int2Str(perMonth1);    // MonthInterval
        breakdown += '';                     // MonthWeek (empty)
        breakdown += '';                     // MonthWeekday (empty)
    }
    else // Specific weekday
    {
        breakdown += '';                     // MonthDay (empty)
        breakdown += int2Str(perMonth2);    // MonthInterval

        // MonthWeek
        WeekOfMonth weekEnum = weekOfMonth;
        breakdown += enum2Str(weekEnum);

        // MonthWeekday
        WeekDays dayEnum = dayValue;
        breakdown += enum2Str(dayEnum);
    }

    // 4 empty values for Year fields (not 5!)
    for (i = 1; i <= 4; i++)
    {
        breakdown += '';
    }

    return breakdown;
}

/// <summary>
/// Year pattern breakdown (13 values)
/// </summary>
private container buildYearBreakdown(container _pattern)
{
    container breakdown = conNull();
    int type, weekOfMonth, dayValue, monthValue;
    int i;

    [type, weekOfMonth, dayValue, monthValue] = _pattern;

    // Skip first 9 columns (not 10!)
    for (i = 1; i <= 9; i++)
    {
        breakdown += '';
    }

    // YearType
    breakdown += (type == 1 ? 'OnceAYear' : 'SpecificWeekday');

    if (type == 1) // Once a year
    {
        breakdown += '';  // YearWeek (empty)
        breakdown += '';  // YearWeekday (empty)
        breakdown += '';  // YearMonth (empty)
    }
    else // Specific weekday
    {
        // YearWeek
        WeekOfMonth weekEnum = weekOfMonth;
        breakdown += enum2Str(weekEnum);

        // YearWeekday
        WeekDays dayEnum = dayValue;
        breakdown += enum2Str(dayEnum);

        // YearMonth
        MonthsOfYear monthEnum = monthValue;
        breakdown += enum2Str(monthEnum);
    }

    return breakdown;
}

/// <summary>
/// Get depends on tasks as comma-separated RecId list
/// </summary>
private str getDependsOnTasks(RefRecId _batchTaskRecId)
{
    BatchConstraints    constraint;
    str                 result = '';
    boolean             first = true;

    while select constraint
        order by constraint.DependsOnBatchId
        where constraint.BatchId == _batchTaskRecId
    {
        if (!first)
        {
            result += ',';
        }
        result += int642Str(constraint.DependsOnBatchId);
        first = false;
    }

    return result;
}

/// <summary>
/// Get expected status as comma-separated list (matching order of depends-on tasks)
/// </summary>
private str getExpectedStatus(RefRecId _batchTaskRecId)
{
    BatchConstraints    constraint;
    str                 result = '';
    boolean             first = true;

    while select constraint
        order by constraint.DependsOnBatchId
        where constraint.BatchId == _batchTaskRecId
    {
        if (!first)
        {
            result += ',';
        }
        result += enum2Str(constraint.ExpectedStatus);
        first = false;
    }

    return result;
}

/// <summary>
/// Get alerts string for batch job
/// Format: userid1:ended,error,popup;userid2:error,email
/// </summary>
private str getAlertsString(RefRecId _batchJobRecId)
{
    BatchJobAlerts  alert;
    str             result = '';
    str             userAlerts;
    boolean         firstUser = true;

    while select alert
        where alert.BatchJobId == _batchJobRecId
    {
        if (!firstUser)
        {
            result += ';';
        }

        userAlerts = alert.UserId + ':';
        boolean firstFlag = true;

        if (alert.BatchJobEnded)
        {
            if (!firstFlag) userAlerts += ',';
            userAlerts += 'ended';
            firstFlag = false;
        }
        if (alert.BatchJobError)
        {
            if (!firstFlag) userAlerts += ',';
            userAlerts += 'error';
            firstFlag = false;
        }
        if (alert.BatchJobCanceled)
        {
            if (!firstFlag) userAlerts += ',';
            userAlerts += 'canceled';
            firstFlag = false;
        }
        if (alert.Popup)
        {
            if (!firstFlag) userAlerts += ',';
            userAlerts += 'popup';
            firstFlag = false;
        }
        if (alert.Email)
        {
            if (!firstFlag) userAlerts += ',';
            userAlerts += 'email';
            firstFlag = false;
        }

        result += userAlerts;
        firstUser = false;
    }

    return result;
}

/// <summary>
/// Convert container to base64 string
/// </summary>
private str containerToBase64String(container _con)
{
    return con2Base64Str(_con);
}

/// <summary>
/// Calculate chunk count needed
/// </summary>
private int calculateChunkCount(str _data)
{
    return (_data ? ((strLen(_data) - 1) div #MaxChunkSize) + 1 : 0);
}

/// <summary>
/// Split string into chunks and return as container
/// </summary>
private container splitIntoChunks(str _data, int _maxChunks)
{
    container chunks = conNull();
    int chunkCount = this.calculateChunkCount(_data);
    int i, startPos, chunkLength;

    chunkCount = min(chunkCount, _maxChunks);

    for (i = 1; i <= chunkCount; i++)
    {
        startPos = ((i - 1) * #MaxChunkSize) + 1;
        chunkLength = min(#MaxChunkSize, strLen(_data) - startPos + 1);
        chunks += subStr(_data, startPos, chunkLength);
    }

    return chunks;
}

/// <summary>
/// Finalize export and download
/// </summary>
private void finalizeExport()
{
    writer.createExcelDocument();
    writer.doExcelOutput('A1');
    writer.excelMarkAsBorderAll();
    writer.formatColumWidth();
    writer.finishOutput();

    info(strFmt('Export completed: %1 rows exported', writer.getRowsCount()));
}

/// <summary>
/// Pack/unpack
/// </summary>
public container pack()
{
    return [#CurrentVersion] + [#CurrentList] + [queryRun.pack()];
}

/// <summary>
/// Unpack from serialization
/// </summary>
public boolean unpack(container _packedClass)
{
    Version     version = RunBase::getVersion(_packedClass);
    container   queryCon;

    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, queryCon] = _packedClass;

            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;

        default:
            return false;
    }

    return true;
}

/// <summary>
/// Show query values in dialog
/// </summary>
public boolean showQueryValues()
{
    return true;
}

/// <summary>
/// Can run in new session
/// </summary>
public boolean canRunInNewSession()
{
    return false;
}

/// <summary>
/// Disable batch functionality
/// </summary>
public boolean canGoBatch()
{
    return false;
}

/// <summary>
/// Class description
/// </summary>
static ClassDescription description()
{
    return "Export batch jobs for cross-environment migration";
}

/// <summary>
/// Entry point
/// </summary>
public static void main(Args _args)
{
    METBatchJobMigrationExport export = new METBatchJobMigrationExport();

    if (export.prompt())
    {
        export.run();
    }
}
